function renderPreview(){const el=$('#preview-inner'),p=active();if(!el||!p)return;const old=el.querySelector('.public-page');const scroll=old?.scrollTop||0;window.WishMotion?.clear?.(el);el.innerHTML=previewMarkup(p);const next=el.querySelector('.public-page');if(next)next.scrollTop=scroll;window.WishMotion?.boot(el);updateCountdowns();}
