async function imageFileUpload(file,path){if(!file)return;
 if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)){notify('Formato inválido. Usa PNG, JPG, WebP o GIF.',true);return;}
 remember();
 try{
  let url;
  if(state.mode==='demo'){
   if(file.size>5*1024*1024)throw Error('La imagen no puede superar 5 MB.');
   if(file.type==='image/gif'){if(file.size>1.6*1024*1024)throw Error('GIF demasiado grande para modo local: máximo 1.6 MB. Usa una URL HTTPS alojada externamente o publica con Storage.');url=await new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=()=>rej(Error('No se pudo leer el GIF'));fr.readAsDataURL(file);});}
   else url=await new Promise((res,rej)=>{const reader=new FileReader();reader.onload=()=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas');const scale=Math.min(1,1200/Math.max(im.width,im.height));c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));c.getContext('2d').drawImage(im,0,0,c.width,c.height);res(c.toDataURL('image/webp',.77));};im.onerror=()=>rej(Error('No se pudo abrir la imagen.'));im.src=reader.result;};reader.onerror=()=>rej(Error('No se pudo leer.'));reader.readAsDataURL(file);});
  }else url=await uploadAsset(file);
  if(path.endsWith('.images')){const parts=path.split('.'),block=active().blocks.find(b=>b.id===parts[1]);selectedChange(path,((block?.images||'').trim()+'\n'+url).trim());}else selectedChange(path,url);renderPane();notify('Imagen añadida.');
 }catch(e){notify(e.message,true);}
}
function inferPlatform(value){let h='';try{h=new URL(value).hostname.toLowerCase().replace(/^www\./,'');}catch{};return ({'tiktok.com':'TikTok','instagram.com':'Instagram','youtube.com':'YouTube','youtu.be':'YouTube','twitch.tv':'Twitch','discord.gg':'Discord','discord.com':'Discord','github.com':'GitHub','open.spotify.com':'Spotify','x.com':'X / Twitter','twitter.com':'X / Twitter','steamcommunity.com':'Steam','patreon.com':'Patreon','paypal.me':'PayPal'})[h]||'Web';}
function parseBulkLinks(value){return String(value||'').split(/\r?\n/).slice(0,80).map(row=>{const parts=row.split('|').map(x=>x.trim());const raw=parts.length===1?parts[0]:parts[1],url=safeUrl(raw);if(!url||!/^https?:/i.test(url))return null;const platform=inferPlatform(url);return {...makeBlock('link'),title:(parts.length===1?platform:parts[0])||platform,url,subtitle:parts[2]||'',platform};}).filter(Boolean);}
function harmonize(hex){const n=parseInt(String(hex).replace('#',''),16);const r=(n>>16)&255,g=(n>>8)&255,b=n&255;const rot=(a,k)=>Math.max(0,Math.min(255,Math.round(a*.72+k)));const hx=(a,b,c)=>'#'+[a,b,c].map(v=>Math.max(0,Math.min(255,v)).toString(16).padStart(2,'0')).join('');return [hx(b,r,g),hx(rot(r,5),rot(g,8),rot(b,18)),hx(rot(r,0)/4|0,rot(g,0)/4|0,rot(b,0)/4|0)];}
