async function shareCard(story){const p=active();if(!p)return;const w=story?1080:1200,h=story?1920:630,canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');if(!ctx){notify('El navegador no admite canvas.',true);return;}const t=p.theme,gr=ctx.createLinearGradient(0,0,w,h);gr.addColorStop(0,color(t.bg));gr.addColorStop(.65,color(t.surface));gr.addColorStop(1,color(t.accent));ctx.fillStyle=gr;ctx.fillRect(0,0,w,h);ctx.globalAlpha=.20;for(let i=0;i<25;i++){ctx.beginPath();ctx.arc((i*163)%w,(i*127)%h,8+i%8*9,0,Math.PI*2);ctx.fillStyle='#ffffff';ctx.fill();}ctx.globalAlpha=1;let top=story?590:185;ctx.textAlign='center';ctx.font=`800 ${story?98:72}px sans-serif`;ctx.fillStyle=color(t.text);ctx.shadowColor=color(t.accent);ctx.shadowBlur=35;const title=String(p.title||'Mi universo').slice(0,30);ctx.fillText(title,w/2,top,w-100);ctx.shadowBlur=0;ctx.font=`500 ${story?35:28}px sans-serif`;ctx.fillStyle=color(t.secondary);let desc=String(p.description||'').split('\n')[0].slice(0,75);ctx.fillText(desc,w/2,top+(story?95:70),w-100);ctx.font=`800 ${story?37:25}px sans-serif`;ctx.fillStyle=color(t.accent);ctx.fillText(`✦ @${p.slug}  ·  WISHLINKS`,w/2,story?h-380:470,w-100);ctx.font=`400 ${story?27:20}px sans-serif`;ctx.fillStyle=color(t.text);ctx.fillText('Mis redes, mis proyectos, mi propio universo',w/2,story?h-320:520,w-100);canvas.toBlob(blob=>{if(!blob){notify('No se pudo crear la imagen',true);return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${p.slug}-${story?'story':'share'}-wishlinks.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);notify('Imagen promocional descargada');},'image/png');}
