 document.addEventListener('input',e=>{const f=e.target.closest('#block-filter');if(f){state.blockFilter=f.value;$$('[data-drag-id]').forEach(el=>{const b=active()?.blocks.find(b=>b.id===el.dataset.dragId);el.style.display=!state.blockFilter||String(b?.title||b?.text||b?.type||'').toLowerCase().includes(state.blockFilter.toLowerCase())?'':'none';});return;}if(e.target.id==='command-search'){const q=e.target.value.toLowerCase();$$('.command-results button').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q));return;}const el=e.target.closest('[data-bind]');if(!el)return;if(el.type==='checkbox')return;let value=el.value;if(el.type==='range')value=Number(value);selectedChange(el.dataset.bind,value);});
